def budget(pool,headroom):
    names=('nodes','max_surge','max_unavailable','vcpu_per_node')
    if any(type(pool[k]) is not int or pool[k]<0 for k in names) or pool['nodes']<1 or pool['vcpu_per_node']<1 or pool['max_surge']+pool['max_unavailable']==0:raise ValueError('explicit single-zone surge configuration required')
    if any(type(headroom[k]) is not int or headroom[k]<0 for k in ('vcpu','node_ips','pod_blocks')):raise ValueError('nonnegative already-available headroom required')
    capacity=min(headroom['vcpu']//pool['vcpu_per_node'],headroom['node_ips'],headroom['pod_blocks'])
    surge=min(pool['max_surge'],capacity)
    parallel=min(pool['nodes'],surge+pool['max_unavailable'])
    return {'extra_node_capacity':capacity,'surge_nodes':surge,'parallel_nodes':parallel,'blocked':parallel==0,'actual_capacity_verified':False}
```

